import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg'; 

const QuanLyThongBao = () => {
    const [tabActive, setTabActive] = useState('view');
    const [title, setTitle] = useState('');
    const [content, setContent] = useState('');
    const [targetRoom, setTargetRoom] = useState('All'); // Mặc định là gửi cho tất cả

    const [notifications, setNotifications] = useState(() => {
        const savedNotis = localStorage.getItem('building_notifications');
        return savedNotis ? JSON.parse(savedNotis) : [
            {
                id: 1,
                room: "All", // Liên kết số phòng: "All" hoặc "101", "202"...
                title: "Thông báo hệ thống",
                body: "Chào mừng bạn đến với hệ thống quản lý tòa nhà A&RMS.",
                date: "22/04/2026",
                sender: "Admin"
            }
        ];
    });

    const [showDeleteConfirm, setShowDeleteConfirm] = useState(false);
    const [notiToDelete, setNotiToDelete] = useState(null);

    useEffect(() => {
        localStorage.setItem('building_notifications', JSON.stringify(notifications));
    }, [notifications]);

    // HÀM GỬI THÔNG BÁO (Chuẩn bị sẵn payload cho Backend)
    const handleSendNotification = () => {
        if (!title.trim() || !content.trim()) return;

        const newNoti = {
            id: Date.now(), // Backend sẽ tự gen
            room: targetRoom, // LIÊN KẾT SỐ PHÒNG Ở ĐÂY
            title: title,
            body: content,
            date: new Date().toLocaleDateString('vi-VN'),
            sender: "Admin"
        };

        /* SAU NÀY GẮN API:
           const res = await axios.post('/api/notifications', newNoti);
           setNotifications([res.data, ...notifications]);
        */

        setNotifications([newNoti, ...notifications]);
        setTitle('');
        setContent('');
        setTargetRoom('All');
        setTabActive('view');
    };

    const confirmDelete = () => {
        setNotifications(notifications.filter(n => n.id !== notiToDelete));
        setShowDeleteConfirm(false);
        setNotiToDelete(null);
    };

    return (
        <div style={{
            flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', 
            backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover',
            backgroundPosition: 'center', overflow: 'hidden', position: 'relative',
            height: 'calc(100vh - 120px)'
        }} className="glass-card">

            {/* Modal xác nhận xóa */}
            {showDeleteConfirm && (
                <div style={modalOverlayStyle}>
                    <div style={modalBoxStyle}>
                        <p style={{ fontWeight: 'bold', marginBottom: '20px' }}>Xác nhận xóa thông báo?</p>
                        <div style={{ display: 'flex', gap: '10px', justifyContent: 'center' }}>
                            <button onClick={confirmDelete} style={btnConfirmStyle}>Xác nhận</button>
                            <button onClick={() => setShowDeleteConfirm(false)} style={btnCancelStyle}>Hủy</button>
                        </div>
                    </div>
                </div>
            )}

            {/* Header Tabs */}
            <div style={{ padding: '20px', display: 'flex', gap: '15px', flexShrink: 0, background: 'rgba(0,0,0,0.2)' }}>
                <button onClick={() => setTabActive('view')} 
                    style={{...tabButtonStyle, backgroundColor: tabActive === 'view' ? '#333' : 'rgba(255,255,255,0.6)', color: tabActive === 'view' ? '#fff' : '#333'}}>
                    Khung thông báo
                </button>
                <button onClick={() => setTabActive('send')}
                    style={{...tabButtonStyle, backgroundColor: tabActive === 'send' ? '#8b5e5e' : 'rgba(255,255,255,0.6)', color: tabActive === 'send' ? '#fff' : '#333'}}>
                    Gửi thông báo
                </button>
            </div>

            <div style={{ flex: 1, padding: '20px', overflow: 'hidden' }}>
                {tabActive === 'view' ? (
                    <div className="custom-scrollbar" style={scrollContainerStyle}>
                        {notifications.length > 0 ? notifications.map(noti => (
                            <div key={noti.id} style={notiCardStyle}>
                                <div onClick={() => { setNotiToDelete(noti.id); setShowDeleteConfirm(true); }}
                                    style={deleteBtnStyle} className="delete-hover">✕</div>

                                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
                                    <div>
                                        <span style={roomTagStyle}>
                                            {noti.room === 'All' ? '📢 Toàn tòa nhà' : `🏠 Phòng ${noti.room}`}
                                        </span>
                                        <span style={{ fontWeight: 'bold', color: '#333', fontSize: '16px', marginLeft: '10px' }}>{noti.title}</span>
                                    </div>
                                    <span style={{ fontSize: '12px', color: '#999' }}>{noti.date}</span>
                                </div>
                                <p style={notiBodyStyle}>{noti.body}</p>
                            </div>
                        )) : (
                            <div style={emptyStateStyle}>Chưa có thông báo nào.</div>
                        )}
                    </div>
                ) : (
                    /* FORM GỬI THÔNG BÁO TỐI ƯU BACKEND */
                    <div style={sendFormStyle}>
                        <div style={{ display: 'flex', gap: '15px' }}>
                            <select 
                                value={targetRoom} 
                                onChange={(e) => setTargetRoom(e.target.value)}
                                style={roomSelectStyle}
                            >
                                <option value="All">Gửi tất cả phòng</option>
                                <option value="101">Phòng 101</option>
                                <option value="102">Phòng 102</option>
                                {/* Sau này Map danh sách phòng từ Backend vào đây */}
                            </select>
                            <input 
                                style={{...inputStyle, flex: 1}}
                                placeholder="Tiêu đề thông báo..."
                                value={title}
                                onChange={(e) => setTitle(e.target.value)}
                            />
                        </div>
                        <textarea 
                            style={textareaStyle}
                            placeholder="Nội dung thông báo..."
                            value={content}
                            onChange={(e) => setContent(e.target.value)}
                        />
                        <button 
                            onClick={handleSendNotification}
                            disabled={!title.trim() || !content.trim()}
                            style={{ 
                                ...btnSendStyle,
                                opacity: (title.trim() && content.trim()) ? 1 : 0.5,
                            }}
                        >Gửi ngay</button>
                    </div>
                )}
            </div>

            <style>{`
                .custom-scrollbar::-webkit-scrollbar { width: 6px; }
                .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.3); border-radius: 10px; }
                .delete-hover:hover { color: #dc3545 !important; transform: scale(1.2); transition: 0.2s; }
            `}</style>
        </div>
    );
};

// --- STYLES ---
const scrollContainerStyle = { height: '100%', overflowY: 'auto', display: 'flex', flexDirection: 'column', gap: '12px', paddingRight: '10px' };
const tabButtonStyle = { padding: '10px 25px', borderRadius: '20px', border: 'none', fontWeight: 'bold', cursor: 'pointer' };
const notiCardStyle = { backgroundColor: 'rgba(255,255,255,0.95)', padding: '18px', borderRadius: '20px', position: 'relative', flexShrink: 0 };
const roomTagStyle = { backgroundColor: '#e9ecef', color: '#495057', padding: '3px 10px', borderRadius: '8px', fontSize: '11px', fontWeight: 'bold', textTransform: 'uppercase' };
const notiBodyStyle = { margin: 0, fontSize: '14px', color: '#444', lineHeight: '1.5', whiteSpace: 'pre-wrap' };
const deleteBtnStyle = { position: 'absolute', top: '15px', right: '20px', cursor: 'pointer', color: '#ccc' };
const sendFormStyle = { backgroundColor: 'rgba(255,255,255,0.2)', backdropFilter: 'blur(10px)', borderRadius: '25px', padding: '25px', display: 'flex', flexDirection: 'column', gap: '15px' };
